contract SaleClockAuction is ClockAuction {
    bool public isSaleClockAuction = true;
    uint256 public gen0SaleCount;
    uint256[5] public lastGen0SalePrices;
    uint256 public constant SurpriseValue = 10 * 1e15; // Changed from 10 finney to 10 * 1e15
    uint256[] public CommonPanda;
    uint256[] public RarePanda;
    uint256 public CommonPandaIndex;
    uint256 public RarePandaIndex;

    constructor(address _nftAddr, uint256 _cut) public ClockAuction(_nftAddr, _cut) {
        CommonPandaIndex = 1;
        RarePandaIndex = 1;
    }

    function createAuction(
        uint256 _tokenId,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration,
        address _seller
    ) external override {
        require(_startingPrice == uint256(uint128(_startingPrice)));
        require(_endingPrice == uint256(uint128(_endingPrice)));
        require(_duration == uint256(uint64(_duration)));
        require(msg.sender == address(nonFungibleContract));
        _escrow(_seller, _tokenId);
        Auction memory auction = Auction(
            _seller,
            uint128(_startingPrice),
            uint128(_endingPrice),
            uint64(_duration),
            uint64(block.timestamp),
            0
        );
        _addAuction(_tokenId, auction);
    }

    function createGen0Auction(
        uint256 _tokenId,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration,
        address _seller
    ) external {
        require(_startingPrice == uint256(uint128(_startingPrice)));
        require(_endingPrice == uint256(uint128(_endingPrice)));
        require(_duration == uint256(uint64(_duration)));
        require(msg.sender == address(nonFungibleContract));
        _escrow(_seller, _tokenId);
        Auction memory auction = Auction(
            _seller,
            uint128(_startingPrice),
            uint128(_endingPrice),
            uint64(_duration),
            uint64(block.timestamp),
            1
        );
        _addAuction(_tokenId, auction);
    }

    function bid(uint256 _tokenId) external payable override {
        uint64 isGen0 = tokenIdToAuction[_tokenId].isGen0;
        uint256 price = _bid(_tokenId, msg.value);
        _transfer(msg.sender, _tokenId);
        if (isGen0 == 1) {
            lastGen0SalePrices[gen0SaleCount % 5] = price;
            gen0SaleCount++;
        }
    }

    function createPanda(uint256 _tokenId, uint256 _type) external {
        require(msg.sender == address(nonFungibleContract));
        if (_type == 0) {
            CommonPanda.push(_tokenId);
        } else {
            RarePanda.push(_tokenId);
        }
    }

    function surprisePanda() external payable {
        bytes32 bHash = keccak256(abi.encodePacked(blockhash(block.number), blockhash(block.number-1)));
        uint256 PandaIndex;
        if (bHash[25] > 0xC8) {
            require(RarePanda.length >= RarePandaIndex);
            PandaIndex = RarePandaIndex;
            RarePandaIndex++;
        } else {
            require(CommonPanda.length >= CommonPandaIndex);
            PandaIndex = CommonPandaIndex;
            CommonPandaIndex++;
        }
        _transfer(msg.sender, PandaIndex);
    }

    function packageCount() external view returns(uint256 common, uint256 surprise) {
        common = CommonPanda.length + 1 - CommonPandaIndex;
        surprise = RarePanda.length + 1 - RarePandaIndex;
    }

    function averageGen0SalePrice() external view returns (uint256) {
        uint256 sum = 0;
        for (uint256 i = 0; i < 5; i++) {
            sum += lastGen0SalePrices[i];
        }
        return sum / 5;
    }
}

contract SaleClockAuctionERC20 is ClockAuction {
    bool public isSaleClockAuctionERC20 = true;
    mapping(uint256 => address) public tokenIdToErc20Address;
    mapping(address => uint256) public erc20ContractsSwitcher;
    mapping(address => uint256) public balances;

    event AuctionERC20Created(uint256 tokenId, uint256 startingPrice, uint256 endingPrice, uint256 duration, address erc20Contract);

    constructor(address _nftAddr, uint256 _cut) public ClockAuction(_nftAddr, _cut) {}

    function erc20ContractSwitch(address _erc20address, uint256 _onoff) external {
        require(msg.sender == address(nonFungibleContract));
        require(_erc20address != address(0));
        erc20ContractsSwitcher[_erc20address] = _onoff;
    }

    function createAuction(
        uint256 _tokenId,
        address _erc20Address,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration,
        address _seller
    ) external {
        require(_startingPrice == uint256(uint128(_startingPrice)));
        require(_endingPrice == uint256(uint128(_endingPrice)));
        require(_duration == uint256(uint64(_duration)));
        require(msg.sender == address(nonFungibleContract));
        require(erc20ContractsSwitcher[_erc20Address] > 0);
        _escrow(_seller, _tokenId);
        Auction memory auction = Auction(
            _seller,
            uint128(_startingPrice),
            uint128(_endingPrice),
            uint64(_duration),
            uint64(block.timestamp),
            0
        );
        _addAuctionERC20(_tokenId, auction, _erc20Address);
        tokenIdToErc20Address[_tokenId] = _erc20Address;
    }

    function _addAuctionERC20(uint256 _tokenId, Auction memory _auction, address _erc20address) internal {
        require(_auction.duration >= 1 minutes);
        tokenIdToAuction[_tokenId] = _auction;
        emit AuctionERC20Created(_tokenId, _auction.startingPrice, _auction.endingPrice, _auction.duration, _erc20address);
    }

    function bid(uint256 _tokenId) external payable override {
        // do nothing
    }

    function bidERC20(uint256 _tokenId, uint256 _amount) external {
        address _erc20address = tokenIdToErc20Address[_tokenId];
        require(_erc20address != address(0));
        uint256 price = _bidERC20(_erc20address, msg.sender, _tokenId, _amount);
        _transfer(msg.sender, _tokenId);
        delete tokenIdToErc20Address[_tokenId];
    }

    function cancelAuction(uint256 _tokenId) external override {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        require(msg.sender == auction.seller);
        _cancelAuction(_tokenId, auction.seller);
        delete tokenIdToErc20Address[_tokenId];
    }

    function withdrawERC20Balance(address _erc20Address, address _to) external returns(bool) {
        require(balances[_erc20Address] > 0);
        require(msg.sender == address(nonFungibleContract));
        ERC20(_erc20Address).transfer(_to, balances[_erc20Address]);
        return true;
    }

    function _bidERC20(address _erc20Address, address _buyerAddress, uint256 _tokenId, uint256 _bidAmount) internal returns (uint256) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        uint256 price = _currentPrice(auction);
        require(_bidAmount >= price);
        address seller = auction.seller;
        _removeAuction(_tokenId);
        if (price > 0) {
            uint256 auctioneerCut = _computeCut(price);
            uint256 sellerProceeds = price - auctioneerCut;
            require(ERC20(_erc20Address).transferFrom(_buyerAddress, seller, sellerProceeds));
            if (auctioneerCut > 0) {
                require(ERC20(_erc20Address).transferFrom(_buyerAddress, address(this), auctioneerCut));
                balances[_erc20Address] += auctioneerCut;
            }
        }
        emit AuctionSuccessful(_tokenId, price, msg.sender);
        return price;
    }
}

contract PandaAuction is PandaBreeding {
    function setSaleAuctionAddress(address _address) external onlyCEO {
        SaleClockAuction candidateContract = SaleClockAuction(_address);
        require(candidateContract.isSaleClockAuction());
        saleAuction = _address;
    }

    function setSaleAuctionERC20Address(address _address) external onlyCEO {
        SaleClockAuctionERC20 candidateContract = SaleClockAuctionERC20(_address);
        require(candidateContract.isSaleClockAuctionERC20());
        saleAuctionERC20 = _address;
    }

    function setSiringAuctionAddress(address _address) external onlyCEO {
        SiringClockAuction candidateContract = SiringClockAuction(_address);
        require(candidateContract.isSiringClockAuction());
        siringAuction = _address;
    }

    function createSaleAuction(
        uint256 _pandaId,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration
    ) external whenNotPaused {
        require(_owns(msg.sender, _pandaId));
        require(!isPregnant(_pandaId));
        _approve(_pandaId, saleAuction);
        SaleClockAuction(saleAuction).createAuction(_pandaId, _startingPrice, _endingPrice, _duration, msg.sender);
    }

    function createSaleAuctionERC20(
        uint256 _pandaId,
        address _erc20address,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration
    ) external whenNotPaused {
        require(_owns(msg.sender, _pandaId));
        require(!isPregnant(_pandaId));
        _approve(_pandaId, saleAuctionERC20);
        SaleClockAuctionERC20(saleAuctionERC20).createAuction(_pandaId, _erc20address, _startingPrice, _endingPrice, _duration, msg.sender);
    }

    function switchSaleAuctionERC20For(address _erc20address, uint256 _onoff) external onlyCOO {
        SaleClockAuctionERC20(saleAuctionERC20).erc20ContractSwitch(_erc20address,_onoff);
    }

    function createSiringAuction(
        uint256 _pandaId,
        uint256 _startingPrice,
        uint256 _endingPrice,
        uint256 _duration
    ) external whenNotPaused {
        require(_owns(msg.sender, _pandaId));
        require(isReadyToBreed(_pandaId));
        _approve(_pandaId, siringAuction);
        SiringClockAuction(siringAuction).createAuction(_pandaId, _startingPrice, _endingPrice, _duration, msg.sender);
    }

    function bidOnSiringAuction(
        uint256 _sireId,
        uint256 _matronId
    ) external payable whenNotPaused {
        require(_owns(msg.sender, _matronId));
        require(isReadyToBreed(_matronId));
        require(_canBreedWithViaAuction(_matronId, _sireId));
        uint256 currentPrice = SiringClockAuction(siringAuction).getCurrentPrice(_sireId);
        require(msg.value >= currentPrice + autoBirthFee);
        SiringClockAuction(siringAuction).bid{value: msg.value - autoBirthFee}(_sireId);
        _breedWith(_matronId, _sireId, msg.sender);
    }

    function withdrawAuctionBalances() external onlyCLevel {
        SaleClockAuction(saleAuction).withdrawBalance();
        SiringClockAuction(siringAuction).withdrawBalance();
    }

    function withdrawERC20Balance(address _erc20Address, address _to) external onlyCLevel {
        require(saleAuctionERC20 != address(0));
        SaleClockAuctionERC20(saleAuctionERC20).withdrawERC20Balance(_erc20Address,_to);
    }
}

contract PandaMinting is PandaAuction {
    uint256 public constant GEN0_CREATION_LIMIT = 45000;
    uint256 public constant GEN0_STARTING_PRICE = 100 * 1e15; // Changed from 100 finney to 100 * 1e15
    uint256 public constant GEN0_AUCTION_DURATION = 1 days;
    uint256 public constant OPEN_PACKAGE_PRICE = 10 * 1e15; // Changed from 10 finney to 10 * 1e15

    function createWizzPanda(uint256[2] memory _genes, uint256 _generation, address _owner) external onlyCOO {
        address pandaOwner = _owner;
        if (pandaOwner == address(0)) {
            pandaOwner = cooAddress;
        }
        _createPanda(0, 0, _generation, _genes, pandaOwner);
    }

    function createPanda(uint256[2] memory _genes, uint256 _generation, uint256 _type) external payable onlyCOO whenNotPaused {
        require(msg.value >= OPEN_PACKAGE_PRICE);
        uint256 kittenId = _createPanda(0, 0, _generation, _genes, saleAuction);
        SaleClockAuction(saleAuction).createPanda(kittenId,_type);
    }

    function createGen0Auction(uint256 _pandaId) external onlyCOO {
        require(_owns(msg.sender, _pandaId));
        _approve(_pandaId, saleAuction);
        SaleClockAuction(saleAuction).createGen0Auction(_pandaId, _computeNextGen0Price(), 0, GEN0_AUCTION_DURATION, msg.sender);
    }

    function _computeNextGen0Price() internal view returns(uint256) {
        uint256 avePrice = SaleClockAuction(saleAuction).averageGen0SalePrice();
        require(avePrice == uint256(uint128(avePrice)));
        uint256 nextPrice = avePrice + (avePrice / 2);
        if (nextPrice < GEN0_STARTING_PRICE) {
            nextPrice = GEN0_STARTING_PRICE;
        }
        return nextPrice;
    }
}

contract PandaCore is PandaMinting {
    address public newContractAddress;

    constructor() {
        paused = true;
        ceoAddress = msg.sender;
        cooAddress = msg.sender;
    }

    function init() external onlyCEO whenPaused {
        require(pandas.length == 0);
        uint256[2] memory _genes = [type(uint256).max, type(uint256).max];
        wizzPandaQuota[1] = 100;
        _createPanda(0, 0, 0, _genes, address(0));
    }

    function setNewAddress(address _v2Address) external onlyCEO whenPaused {
        newContractAddress = _v2Address;
    }

    receive() external payable {
        require(msg.sender == address(saleAuction) || msg.sender == address(siringAuction));
    }

    function getPanda(uint256 _id) external view returns (
        bool isGestating,
        bool isReady,
        uint256 cooldownIndex,
        uint256 nextActionAt,
        uint256 siringWithId,
        uint256 birthTime,
        uint256 matronId,
        uint256 sireId,
        uint256 generation,
        uint256[2] memory genes
    ) {
        Panda storage kit = pandas[_id];
        isGestating = (kit.siringWithId != 0);
        isReady = (kit.cooldownEndBlock <= block.number);
        cooldownIndex = uint256(kit.cooldownIndex);
        nextActionAt = uint256(kit.cooldownEndBlock);
        siringWithId = uint256(kit.siringWithId);
        birthTime = uint256(kit.birthTime);
        matronId = uint256(kit.matronId);
        sireId = uint256(kit.sireId);
        generation = uint256(kit.generation);
        genes = kit.genes;
    }

    function unpause() public override onlyCEO whenPaused {
        require(address(saleAuction) != address(0));
        require(address(siringAuction) != address(0));
        require(address(geneScience) != address(0));
        require(newContractAddress == address(0));
        super.unpause();
    }

    function withdrawBalance() external onlyCFO {
        uint256 balance = address(this).balance;
        uint256 subtractFees = (pregnantPandas + 1) * autoBirthFee;
        if (balance > subtractFees) {
            payable(cfoAddress).transfer(balance - subtractFees);
        }
    }
}

